41	// screen. A view is told where it stands, so coming back to it shows what
42	// happened while it was away without it having to ask.
43	func TestASnapshotReachesEveryHeldView(t *testing.T) {
44		dashboard := &fakeView{}
45		ws := &fakeView{}
46		sec := &fakeView{}
