//
// A level rather than a tab: the second table is *about* a row of the first, so
// it is reached with → and left with ← or esc, the way every drill-down in the
// application is reached (Rule 111). Tabs would say the two are siblings.
type level int

const (
	levelRuns level = iota
	levelItems
)

// Model is the jobs view.
type Model struct {
	// runs is the snapshot, every context included. contextName is what the
	// tables filter it by: a run is kept for the session and stamped, so a
	// context switch hides its runs rather than dropping them (D8).
	runs        []jobs.Run
	contextName string

	// frame is the router's bare spinner frame. Bare because it goes into a
	// table cell, which is measured before it is styled (Rule 122).
	frame string

	level   level
	openRun jobs.JobID

	runTable  datatable.Model[jobs.Run]
	itemTable datatable.Model[jobs.Item]

	footer sharedcomponents.FooterMessage

	width, height int
}

// Column indexes, named only where something else refers to them.
const (
	runColumnState = iota
	runColumnKind
	runColumnLabel
)

const itemColumnState = 0

// New builds the view.
//
// The context is read once, here, rather than on every frame: the router drops
// every view on a context switch (reinitializeViews), so a cached name cannot
// go stale. It is the current context by definition — the reading D68 leaves
// alone.
func New(_ *config.Config) Model {
	return Model{
		contextName: config.CurrentContextName(),
		runTable: datatable.New(datatable.Config[jobs.Run]{
			Columns: runColumns(),
			// Newest first. A jobs list is read to find out what is happening
			// now, and ascending would put the session's first run at the top
			// for the rest of the session.
			SortColumn: runColumnStarted,
			SortDesc:   true,
		}),
		itemTable: datatable.New(datatable.Config[jobs.Item]{
			Columns: itemColumns(),
			// The order the batch was dispatched in. It is the only order that
			// means anything here — the items of a run have no natural rank,
			// and re-sorting them by state would move a row under the cursor
			// every time it settled.
			SortColumn: -1,
		}),
	}
}

// runColumnStarted is the last column, and is named because it is the initial
// sort. Declared apart from the block above so the three that are referred to
// by handlers stay together.
const runColumnStarted = 5

// runColumns describes the runs table.
//
// The first column is the run's **state**, not its kind, and it is also where
// the spinner goes. That is the containers table's shape and it is deliberate:
// a jobs list is scanned to find the one that failed and the one still going,
// so the glyph answers the question the reader came with, and the Kind column
// says in a word what sort of work it was.
//
// A state glyph column colours by the semantic status styles rather than by a
// theme.IconStyle role, which is the same choice the containers table makes.
// Roles exist for the icons that name an *object* — a namespace, a repository,
// an image — where the palette should be able to separate them. A state has a
// colour already, and inventing five roles for it would give a theme five ways
// to make "failed" not red.
func runColumns() []datatable.Column[jobs.Run] {
	return []datatable.Column[jobs.Run]{
		{
			Title: "", Sizing: datatable.SizingFixed, MinWidth: datatable.IconColumnWidth,
			// The frame is filled in by the model, so this closure cannot be
			// built here; runRows swaps the cell text instead. See stateCell.
			Cell:  func(r jobs.Run) string { return runStateGlyph(r) },
			Style: func(r jobs.Run) lipgloss.Style { return runStateStyle(r.State()) },
		},
		{
			Title: "Kind", Sizing: datatable.SizingFixed, MinWidth: 8,
			Cell: func(r jobs.Run) string { return string(r.Kind) },
			Less: func(a, b jobs.Run) bool { return a.Kind < b.Kind },
			// The state is searchable here rather than in its own column's
			// Search, so `/failed` and `/scan` both work and the glyph column
			// stays out of the filter (Rule 125).
			Search: func(r jobs.Run) string { return string(r.Kind) + " " + string(r.State()) },
		},
		{
			Title: "Label", Sizing: datatable.SizingContent,
			MinWidth: 14, MaxWidth: 40, Flex: 2, TruncateHead: true,
			Cell:   func(r jobs.Run) string { return r.Label },
			Less:   func(a, b jobs.Run) bool { return strings.ToLower(a.Label) < strings.ToLower(b.Label) },
			Search: func(r jobs.Run) string { return r.Label },
		},
		{
			Title: "Progress", Sizing: datatable.SizingFixed, MinWidth: 9,
			Cell: progressCell,
			// By how far along, not by how many: a 1/2 is further than a 3/12,
			// and sorting by the numerator would put the bigger batch on top
			// for having more left to do.
			Less: func(a, b jobs.Run) bool { return fraction(a) < fraction(b) },
		},
		{
			Title: "State", Sizing: datatable.SizingFixed, MinWidth: 10,
			Cell:  func(r jobs.Run) string { return string(r.State()) },
			Style: func(r jobs.Run) lipgloss.Style { return runStateStyle(r.State()) },
			Less:  func(a, b jobs.Run) bool { return a.State() < b.State() },
		},
		{
			Title: "Started", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 12,
			Cell: func(r jobs.Run) string { return theme.TimeAgo(r.StartedAt) },
			Less: func(a, b jobs.Run) bool { return a.StartedAt.Before(b.StartedAt) },
		},
	}
}

// itemColumns describes one run's targets.
//
// No Started column: an item has no timestamp of its own, and a batch's targets
// all belong to the run's. What an item has that a run does not is Detail — the
// reason a sync was skipped, the fact a scan failed — and that is the column
// worth the width here.
func itemColumns() []datatable.Column[jobs.Item] {
	return []datatable.Column[jobs.Item]{
		{
			Title: "", Sizing: datatable.SizingFixed, MinWidth: datatable.IconColumnWidth,
			Cell:  func(i jobs.Item) string { return itemStateGlyph(i) },
			Style: func(i jobs.Item) lipgloss.Style { return itemStateStyle(i.State) },
		},
		{
			Title: "Target", Sizing: datatable.SizingContent,
			MinWidth: 20, MaxWidth: 60, Flex: 3, TruncateHead: true,
			Cell:   func(i jobs.Item) string { return i.Name() },
			Search: func(i jobs.Item) string { return i.Name() },
		},
		{
			Title: "State", Sizing: datatable.SizingFixed, MinWidth: 10,
			Cell:   func(i jobs.Item) string { return string(i.State) },
			Style:  func(i jobs.Item) lipgloss.Style { return itemStateStyle(i.State) },
			Search: func(i jobs.Item) string { return string(i.State) },
		},
		{
			Title: "Detail", Sizing: datatable.SizingContent, MinWidth: 10, Flex: 2,
			Cell:   func(i jobs.Item) string { return dashIfEmpty(i.Detail) },
			Style:  detailStyle,
			Search: func(i jobs.Item) string { return i.Detail },
		},
	}
}

// progressCell is the "7/12" of a run.
//
// A finished run keeps it. "12/12 · done" beside "3/12 · running" is what makes
// the size of a batch readable at a glance, and blanking it on the settled rows
// would leave the column empty for most of the list.
func progressCell(r jobs.Run) string {
	return strconv.Itoa(r.Done()) + "/" + strconv.Itoa(r.Total())
}

// fraction is how far along a run is, in [0,1]. An empty run is finished.
func fraction(r jobs.Run) float64 {
	if r.Total() == 0 {
		return 1
	}
	return float64(r.Done()) / float64(r.Total())
}

// dashIfEmpty is the placeholder for a cell with nothing in it. It is a dash
// rather than a blank so the column reads as a column (Rule 122's dim
// placeholders).
func dashIfEmpty(s string) string {
	if s == "" {
		return "-"
	}
	return s
}

// detailStyle dims a detail that is only a placeholder. A real one — "already
// there", "scan failed — check logs" — is left in the text colour: it is the
// column's whole purpose, and dimming what the reader came for would be the
// opposite of Rule 122's discipline.
func detailStyle(i jobs.Item) lipgloss.Style {
	if i.Detail == "" {
		return theme.DimStyle
	}
	return lipgloss.NewStyle()
}
