	runs := m.visibleRuns()
	rows := make([]runRow, len(runs))
	for i, run := range runs {
		rows[i] = runRow{Run: run, Frame: m.frame}
	}
	m.runTable.SetItems(rows)

	run, ok := m.openedRun()
	if m.level == levelItems && !ok {
		// Falling back to the list rather than showing an empty one: the run
		// was pruned, so there is nothing to say about it, and a table titled
		// with a label that no longer exists would be worse than the list.
		m.level = levelRuns
		m.itemTable.SetItems(nil)
		return
	}

	items := make([]itemRow, len(run.Items))
	for i, item := range run.Items {
		items[i] = itemRow{Item: item, Frame: m.frame}
	}
	m.itemTable.SetItems(items)
}

// handleKeyMsg routes a key, filter first (Rule 136).
func (m Model) handleKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	if m.table().InEditMode() {
		cmd := m.table().Update(msg)
		return m, cmd
	}

	switch msg.String() {
	case "right":
		return m.openSelected()

	case "left", "esc":
		return m.closeItems()

	case "/":
		return m, m.table().FilterBar().ActivateSearch()
	}

	return m, m.table().Update(msg)
}

// openSelected drills into the run under the cursor (Rule 111: → descends).
func (m Model) openSelected() (tea.Model, tea.Cmd) {
	if open := m.canOpen(); !open.Enabled() {
		return m, m.footer.Warn(open.Reason)
	}
	row, _ := m.runTable.Selected()
	m.openRun = row.Run.ID
	m.level = levelItems
	m.itemTable.GotoTop()
	m.refreshRows()
	m.resize(m.width, m.height)
	return m, nil
}

// closeItems goes back up. At the top level there is nowhere to go: `esc` is
// what a user presses to leave a screen, and this view has no screen behind it
// — the router owns that, and a message saying so would be noise.
func (m Model) closeItems() (tea.Model, tea.Cmd) {
	if m.level == levelRuns {
		return m, nil
	}
	m.level = levelRuns
	m.openRun = 0
	m.resize(m.width, m.height)
	return m, nil
}

// table is whichever level is on screen. Both are datatable.Model over
// different types, so this returns the narrow interface the key handling needs
// rather than one of them.
type activeTable interface {
	InEditMode() bool
	Update(tea.Msg) tea.Cmd
	FilterBar() *sharedFilterBar
}

// resize lays both tables out.
//
// Both, again: the item table is measured for the size it will be opened at, so
// → does not show one frame of a table sized for a window that has since
// changed.
func (m *Model) resize(width, height int) {
	m.width = width
	m.height = height

	// The breadcrumb costs the table a line at the item level (Rule 123): it is
	// rendered in the footer, so GetFooterHeight already asks for it, and the
	// table must not subtract it a second time. What is subtracted here is the
	// header row, like every other table view.
	m.runTable.Resize(width, height-2)
	m.itemTable.Resize(width, height-2)
}

