	sharedcomponents.FooterMsgDuration = time.Millisecond

	// New reads the current context, which lives under the home directory.
	home, err := os.MkdirTemp("", "devdesk-jobsview-test")
	if err != nil {
		log.SetOutput(os.Stderr)
		panic(err)
	}
	_ = os.Setenv("HOME", home)
	_ = os.Setenv("USERPROFILE", home)

	code := m.Run()

	_ = os.RemoveAll(home)
	log.SetOutput(os.Stderr)
	os.Exit(code)
}

